#!/usr/bin/env node
'use strict';

const fs = require('fs');

function fail(message) {
  process.stderr.write(`extract.js: ${message}\n`);
  process.exit(1);
}

const inputPath = process.argv[2];
if (!inputPath) {
  fail('usage: node extract.js <ELF-file>');
}

let file;
try {
  file = fs.readFileSync(inputPath);
} catch (error) {
  fail(error.message);
}

if (
  file.length < 16 ||
  file[0] !== 0x7f ||
  file[1] !== 0x45 ||
  file[2] !== 0x4c ||
  file[3] !== 0x46
) {
  fail('input is not an ELF file');
}

const elfClass = file[4];
const dataEncoding = file[5];
if (elfClass !== 1 && elfClass !== 2) {
  fail(`unsupported ELF class ${elfClass}`);
}
if (dataEncoding !== 1 && dataEncoding !== 2) {
  fail(`unsupported ELF byte order ${dataEncoding}`);
}

const is64 = elfClass === 2;
const littleEndian = dataEncoding === 1;
const headerSize = is64 ? 64 : 52;
if (file.length < headerSize) {
  fail('truncated ELF header');
}

function uint(offset, size) {
  if (!Number.isSafeInteger(offset) || offset < 0 || offset + size > file.length) {
    fail('truncated or invalid ELF structure');
  }

  switch (size) {
    case 2:
      return BigInt(littleEndian
        ? file.readUInt16LE(offset)
        : file.readUInt16BE(offset));
    case 4:
      return BigInt(littleEndian
        ? file.readUInt32LE(offset)
        : file.readUInt32BE(offset));
    case 8:
      return littleEndian
        ? file.readBigUInt64LE(offset)
        : file.readBigUInt64BE(offset);
    default:
      fail(`internal error: unsupported integer size ${size}`);
  }
}

function fileOffset(value, description) {
  if (value > BigInt(Number.MAX_SAFE_INTEGER)) {
    fail(`${description} is too large`);
  }
  const result = Number(value);
  if (result < 0 || result > file.length) {
    fail(`${description} lies outside the file`);
  }
  return result;
}

const programHeaderOffset = uint(is64 ? 32 : 28, is64 ? 8 : 4);
const sectionHeaderOffset = uint(is64 ? 40 : 32, is64 ? 8 : 4);
const programHeaderEntrySize = Number(uint(is64 ? 54 : 42, 2));
let programHeaderCount = Number(uint(is64 ? 56 : 44, 2));
const sectionHeaderEntrySize = Number(uint(is64 ? 58 : 46, 2));
const minimumProgramHeaderSize = is64 ? 56 : 32;

if (programHeaderEntrySize < minimumProgramHeaderSize && programHeaderCount !== 0) {
  fail('invalid program-header entry size');
}

// ELF uses PN_XNUM to store a very large program-header count in section
// header zero's sh_info field.
if (programHeaderCount === 0xffff) {
  if (sectionHeaderOffset === 0n || sectionHeaderEntrySize < (is64 ? 64 : 40)) {
    fail('invalid extended program-header count');
  }
  const sectionZero = fileOffset(sectionHeaderOffset, 'section-header table');
  programHeaderCount = Number(uint(sectionZero + (is64 ? 44 : 28), 4));
}

if (!Number.isSafeInteger(programHeaderCount) || programHeaderCount < 0) {
  fail('invalid program-header count');
}

const tableOffset = fileOffset(programHeaderOffset, 'program-header table');
const tableBytes = programHeaderCount * programHeaderEntrySize;
if (!Number.isSafeInteger(tableBytes) || tableOffset + tableBytes > file.length) {
  fail('truncated program-header table');
}

const words = new Map();
const WORD_SIZE = 4n;

for (let index = 0; index < programHeaderCount; index++) {
  const header = tableOffset + index * programHeaderEntrySize;
  const type = Number(uint(header, 4));
  if (type !== 1) { // PT_LOAD
    continue;
  }

  const segmentFileOffset = uint(header + (is64 ? 8 : 4), is64 ? 8 : 4);
  const virtualAddress = uint(header + (is64 ? 16 : 8), is64 ? 8 : 4);
  const fileSize = uint(header + (is64 ? 32 : 16), is64 ? 8 : 4);
  const memorySize = uint(header + (is64 ? 40 : 20), is64 ? 8 : 4);

  if (fileSize > memorySize) {
    fail(`load segment ${index} has a file size larger than its memory size`);
  }

  const sourceStart = fileOffset(segmentFileOffset, `load segment ${index}`);
  if (fileSize > BigInt(file.length - sourceStart)) {
    fail(`load segment ${index} extends past the end of the file`);
  }

  // Emit only complete, naturally aligned, file-backed 32-bit words. Bytes
  // after p_filesz are zero-filled by an ELF loader, but omitting them keeps
  // this extractor conservative while still recovering the actual values
  // stored in the binary.
  const firstAddress = (virtualAddress + (WORD_SIZE - 1n)) & ~(WORD_SIZE - 1n);
  const fileBackedEnd = virtualAddress + fileSize;

  for (let address = firstAddress; address + WORD_SIZE <= fileBackedEnd; address += WORD_SIZE) {
    const relativeOffset = address - virtualAddress;
    const sourceOffsetBig = segmentFileOffset + relativeOffset;
    const sourceOffset = fileOffset(sourceOffsetBig, `word at virtual address ${address}`);
    const value = littleEndian
      ? file.readUInt32LE(sourceOffset)
      : file.readUInt32BE(sourceOffset);
    words.set(address.toString(), value);
  }
}

if (words.size === 0) {
  fail('ELF file contains no complete words in loadable segments');
}

const entries = [...words.entries()]
  .sort((left, right) => {
    const a = BigInt(left[0]);
    const b = BigInt(right[0]);
    return a < b ? -1 : a > b ? 1 : 0;
  });

// Serialize directly so even 64-bit addresses remain exact JSON object keys.
const output = entries
  .map(([address, value]) => `${JSON.stringify(address)}:${value}`)
  .join(',');
process.stdout.write(`{${output}}\n`);

