const fs = require('fs');
const obj = JSON.parse(fs.readFileSync('out.json', 'utf8'));
const keys = Object.keys(obj);
if (keys.length === 0) throw new Error('empty output');
if (!keys.every(k => /^\d+$/.test(k))) throw new Error('non-decimal address key');
if (!Object.values(obj).every(v => Number.isInteger(v))) throw new Error('non-integer value');
console.log(JSON.stringify({count: keys.length, first: keys.slice(0, 5).map(k => [k, obj[k]]), last: keys.slice(-5).map(k => [k, obj[k]])}, null, 2));
