python3 - <<'PY'
import json, struct
from pathlib import Path
b = Path('a.out').read_bytes()
assert b[:4] == b'\x7fELF'
cls, data = b[4], b[5]
end = '<' if data == 1 else '>'
if cls == 2:
    phoff = struct.unpack_from(end+'Q', b, 32)[0]
    phentsize, phnum = struct.unpack_from(end+'HH', b, 54)
    fmt = end+'IIQQQQQQ'
else:
    phoff = struct.unpack_from(end+'I', b, 28)[0]
    phentsize, phnum = struct.unpack_from(end+'HH', b, 42)
    fmt = end+'IIIIIIII'
expected = {}
for i in range(phnum):
    p = struct.unpack_from(fmt, b, phoff + i*phentsize)
    if p[0] != 1:
        continue
    if cls == 2:
        _, _, off, va, _, filesz, memsz, _ = p
    else:
        _, off, va, _, filesz, memsz, _, _ = p
    start = (va + 3) & ~3
    for addr in range(start, va + filesz - 3, 4):
        pos = off + addr - va
        expected[str(addr)] = int.from_bytes(b[pos:pos+4], 'little' if data == 1 else 'big')
actual = json.loads(Path('out.json').read_text())
assert actual == expected, (len(actual), len(expected))
print(f'independent PT_LOAD comparison passed for {len(actual)} words')
